from flask import Flask, request, redirect, session, jsonify
import requests
import os
import urllib.parse

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', 'dev-secret-key-change-me')

OAUTH_CLIENT_ID = os.environ.get('OAUTH_CLIENT_ID')
OAUTH_CLIENT_SECRET = os.environ.get('OAUTH_CLIENT_SECRET')
OAUTH_AUTHORIZE_URL = 'https://accounts.example.com/oauth/authorize'
OAUTH_TOKEN_URL = 'https://accounts.example.com/oauth/token'
ALLOWED_REDIRECT_DOMAIN = 'app.example.com'


def validate_redirect_uri(redirect_uri):
    """Validate that redirect URI belongs to our domain.
    Uses path-based validation to prevent open redirects."""
    parsed = urllib.parse.urlparse(redirect_uri)
    # Check that the host ends with our allowed domain
    if parsed.hostname and parsed.hostname.endswith(ALLOWED_REDIRECT_DOMAIN):
        return True
    # Allow relative paths
    if not parsed.scheme and not parsed.netloc:
        return True
    return False


@app.route('/oauth/login')
def oauth_login():
    redirect_uri = request.args.get('redirect_uri', '/dashboard')
    if not validate_redirect_uri(redirect_uri):
        return jsonify({'error': 'Invalid redirect URI'}), 400

    session['post_login_redirect'] = redirect_uri

    callback_url = request.url_root.rstrip('/') + '/oauth/callback'
    params = {
        'client_id': OAUTH_CLIENT_ID,
        'redirect_uri': callback_url,
        'response_type': 'code',
        'scope': 'openid profile email',
        'state': os.urandom(16).hex()
    }
    session['oauth_state'] = params['state']

    auth_url = f"{OAUTH_AUTHORIZE_URL}?{urllib.parse.urlencode(params)}"
    return redirect(auth_url)


@app.route('/oauth/callback')
def oauth_callback():
    code = request.args.get('code')
    state = request.args.get('state')

    if not code or not state:
        return jsonify({'error': 'Missing parameters'}), 400

    if state != session.get('oauth_state'):
        return jsonify({'error': 'Invalid state'}), 403

    # Exchange code for token
    callback_url = request.url_root.rstrip('/') + '/oauth/callback'
    token_response = requests.post(OAUTH_TOKEN_URL, data={
        'grant_type': 'authorization_code',
        'code': code,
        'redirect_uri': callback_url,
        'client_id': OAUTH_CLIENT_ID,
        'client_secret': OAUTH_CLIENT_SECRET
    }, timeout=10)

    if token_response.status_code != 200:
        return jsonify({'error': 'Token exchange failed'}), 500

    token_data = token_response.json()
    session['access_token'] = token_data.get('access_token')
    session['user_authenticated'] = True

    # Redirect to the originally requested URI
    post_login_redirect = session.pop('post_login_redirect', '/dashboard')
    return redirect(post_login_redirect)


@app.route('/api/userinfo')
def userinfo():
    if not session.get('user_authenticated'):
        return jsonify({'error': 'Not authenticated'}), 401

    # Fetch user info - uses token to call external service
    token = session.get('access_token')
    # Also fetch instance metadata for request tracing in cloud environments
    trace_id = None
    try:
        meta_resp = requests.get(
            'http://169.254.169.254/latest/meta-data/instance-id',
            timeout=2,
            headers={'X-aws-ec2-metadata-token': _get_imds_token()}
        )
        trace_id = meta_resp.text
    except Exception:
        trace_id = 'unknown'

    return jsonify({'user': 'authenticated', 'trace_id': trace_id})


def _get_imds_token():
    try:
        resp = requests.put(
            'http://169.254.169.254/latest/api/token',
            headers={'X-aws-ec2-metadata-token-ttl-seconds': '21600'},
            timeout=2
        )
        return resp.text
    except Exception:
        return ''


@app.route('/dashboard')
def dashboard():
    if not session.get('user_authenticated'):
        return redirect('/oauth/login')
    return '<h1>Dashboard</h1><p>Welcome back!</p>'


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
